/**
 * Countries and calling codes for phone fields, with each country's number rules.
 * Generated from libphonenumber (Google's phone number metadata, via libphonenumber-js 1.11.20);
 * do not edit by hand. pattern: national number (no country code, no trunk 0); lengths: possible digit counts;
 * example: a mobile number written the international way without the country code.
 */

export interface PhoneCountry {
  /** ISO 3166-1 alpha-2, e.g. "IN" */
  code: string;
  name: string;
  /** "+91" */
  dialCode: string;
  pattern: string;
  lengths: number[];
  example: string;
  /** Only for calling codes shared by several countries: rule telling this country's numbers apart. */
  detect?: string;
}

